#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Fragments;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using PVZEngine.Armors;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace MVZ2.GameContent.Armors
{
    [ArmorBehaviourDefinition(VanillaArmorBehaviourNames.sarcophagus)]
    public class Sarcophagus : ArmorBehaviourDefinition
    {
        public Sarcophagus(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(LevelCallbacks.POST_ENTITY_DEATH, PostEntityDeathCallback);
            AddTrigger(LevelCallbacks.POST_DESTROY_ARMOR, PostArmorDestroyCallback);
            AddAura(new HeavyAura());
        }
        private void PostArmorDestroyCallback(LevelCallbacks.PostArmorDestroyParams param, CallbackResult result)
        {
            var entity = param.entity;
            var armor = param.armor;
            var info = param.info;
            if (!armor.Definition.HasBehaviour(this))
                return;
            var pos = entity.Position;
            entity.CreateFragmentAndPlay(pos, VanillaFragmentID.sarcophagus, emitSpeed: 500);
            var gasParam = entity.GetSpawnParams();
            entity.Spawn(VanillaEffectID.mummyGas, entity.Position, gasParam);
            entity.PlaySound(VanillaSoundID.poisonCast);
        }
        private void PostEntityDeathCallback(LevelCallbacks.PostEntityDeathParams param, CallbackResult result)
        {
            var entity = param.entity;
            var info = param.deathInfo;
            if (info.HasEffect(VanillaDamageEffects.REMOVE_ON_DEATH))
                return;
            var armor = entity.GetMainArmor();
            if (armor == null)
                return;
            if (!armor.Definition.HasBehaviour(this))
                return;
            armor.Destroy();
        }
        public class HeavyAura : AuraEffectDefinition
        {
            public HeavyAura() : base(VanillaBuffID.Enemy.heavyCannon, 4)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var armor = auraEffect.Source as Armor;
                if (armor == null)
                    return;
                results.Add(armor.Owner);
            }
        }
    }
}
